#nullable enable

using System.Collections.Generic;
using System.Linq;
using Catamailer.Domain;
using Xunit;

namespace Catamailer.Application.Tests
{
    /// <summary>
    /// Classe de test validant le comportement du moteur de classification (Étape 1).
    /// </summary>
    public class ClassificationEngineTests
    {
        private MailMetadata CreateDummyMetadata(
            string subject = "Sujet",
            string sender = "test@test.com",
            IEnumerable<string>? recipients = null,
            IEnumerable<string>? existingCategories = null)
        {
            return new MailMetadata(
                "ID",
                subject,
                sender,
                null,
                recipients ?? new List<string>(),
                new List<string>(),
                existingCategories);
        }

        [Fact]
        public void Classify_ShouldReturnNull_WhenNoRulesProvided()
        {
            // Arrange
            var engine = new ClassificationEngine();
            var rules = new List<DictionaryRule>();
            var metadata = CreateDummyMetadata();

            // Act
            ClassificationResult? result = engine.Classify(metadata, rules);

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void Classify_ShouldReturnCategoryAndAscendanceChain_WhenSubjectKeywordMatches()
        {
            // Arrange
            var engine = new ClassificationEngine();
            
            var rootCategory = new CategoryNode("Projet");
            var childCategory = new CategoryNode("Alpha");
            rootCategory.AddChild(childCategory);

            var rule = new DictionaryRule(childCategory, subjectKeywords: new[] { "Urgent" });
            var rules = new List<DictionaryRule> { rule };
            var metadata = CreateDummyMetadata(subject: "Message Urgent pour le projet");

            // Act
            ClassificationResult? result = engine.Classify(metadata, rules);

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Alpha", result.MatchedCategory.Name);
            Assert.Equal(2, result.AppliedCategories.Count);
            Assert.Equal("Projet", result.AppliedCategories[0].Name);
            Assert.Equal("Alpha", result.AppliedCategories[1].Name);
            Assert.Equal(MailField.Subject, result.TriggerField);
            Assert.Equal("Urgent", result.MatchedKeyword);
        }

        [Fact]
        public void Classify_ShouldReturnCategory_WhenKeywordMatchesRecipient()
        {
            // Arrange
            var engine = new ClassificationEngine();

            var category = new CategoryNode("Direction");
            var rule = new DictionaryRule(category, recipientKeywords: new[] { "boss@company.com" });
            var rules = new List<DictionaryRule> { rule };

            var recipients = new List<string> { "employe@company.com", "boss@company.com" };
            var metadata = CreateDummyMetadata(recipients: recipients);

            // Act
            ClassificationResult? result = engine.Classify(metadata, rules);

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Direction", result.MatchedCategory.Name);
            Assert.Equal(MailField.Recipients, result.TriggerField);
            Assert.Equal("boss@company.com", result.MatchedKeyword);
        }

        [Fact]
        public void ClassifyAll_ShouldEvaluateAllRules_AndReturnMultipleMatchesWithTriggerDetails()
        {
            // Arrange
            var engine = new ClassificationEngine();

            var catComito = new CategoryNode("Comitologie");
            var catCeda = new CategoryNode("CEDA");
            catComito.AddChild(catCeda);

            var catStaff = new CategoryNode("Staff");
            catComito.AddChild(catStaff);

            var catAutre = new CategoryNode("Autre");

            var rule1 = new DictionaryRule(catCeda, subjectKeywords: new[] { "[CEDA]", "Revue" });
            var rule2 = new DictionaryRule(catStaff, senderKeywords: new[] { "claire.lecourtier@assurance-maladie.fr" });
            var rule3 = new DictionaryRule(catAutre, subjectKeywords: new[] { "Inexistant" });

            var metadata = CreateDummyMetadata(
                subject: "[CEDA] : Ordre du jour",
                sender: "claire.lecourtier@assurance-maladie.fr",
                existingCategories: new[] { "Comitologie-CEDA" });

            // Act
            var results = engine.ClassifyAll(metadata, new[] { rule1, rule2, rule3 });

            // Assert
            Assert.Single(metadata.ExistingCategories!);
            Assert.Equal("Comitologie-CEDA", metadata.ExistingCategories!.First());

            Assert.Equal(2, results.Count);

            var firstMatch = results[0];
            Assert.Equal("CEDA", firstMatch.MatchedCategory.Name);
            Assert.Equal(MailField.Subject, firstMatch.TriggerField);
            Assert.Equal("[CEDA]", firstMatch.MatchedKeyword);
            Assert.Equal(2, firstMatch.AppliedCategories.Count);

            var secondMatch = results[1];
            Assert.Equal("Staff", secondMatch.MatchedCategory.Name);
            Assert.Equal(MailField.Sender, secondMatch.TriggerField);
            Assert.Equal("claire.lecourtier@assurance-maladie.fr", secondMatch.MatchedKeyword);
        }
    }
}